dashboard.definition:
{
    "title": "Campus-Netzwerk",
    "description": "Netzwerk: Catalyst Center Device Health je Haus, Issues, ISE RADIUS, ThousandEyes-Tests und IOS-XE-Syslog",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_building": {
            "type": "input.dropdown",
            "title": "Haus",
            "options": {
                "items": [
                    {
                        "label": "Alle Haeuser",
                        "value": "*"
                    },
                    {
                        "label": "Haus A - Innere Medizin",
                        "value": "A"
                    },
                    {
                        "label": "Haus B - Chirurgisches Zentrum",
                        "value": "B"
                    },
                    {
                        "label": "Haus C - Akut- und Intensivzentrum",
                        "value": "C"
                    },
                    {
                        "label": "Haus D - Frauen, Kind und Psyche",
                        "value": "D"
                    }
                ],
                "token": "building",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "device": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_health": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:dnac:devicehealth\" Building=\"$building$\" earliest=-20m\n| stats latest(HealthScore) as HealthScore latest(Reachability) as Reachability latest(DeviceFamily) as DeviceFamily latest(DeviceType) as DeviceType latest(Role) as Role latest(Location) as Location latest(SoftwareVersion) as SoftwareVersion latest(ClientCount) as ClientCount latest(Building) as Building by DeviceName",
                "enableSmartSources": true
            },
            "name": "Device Health"
        },
        "ds_k_reach": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_health",
                "query": "| stats count(eval(Reachability=\"Reachable\")) as r count as n | eval \"Erreichbar %\"=round(100 * r / n, 1) | fields \"Erreichbar %\""
            }
        },
        "ds_k_down": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_health",
                "query": "| where Reachability!=\"Reachable\" | stats count as Unreachable"
            }
        },
        "ds_k_score": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.network.health_score\" building=\"$building$\" span=10m | rename v as \"Health Score\"",
                "enableSmartSources": true
            }
        },
        "ds_k_clients": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.network.clients\" building=\"$building$\" span=15m | rename v as \"WLAN-Clients\"",
                "enableSmartSources": true
            }
        },
        "ds_k_p1": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:dnac:issue\" Priority=P1 Building=\"$building$\" | stats dc(IssueID) as \"P1 Issues\"",
                "enableSmartSources": true
            }
        },
        "ds_k_ise": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ise:syslog\" \"CISE_Failed_Attempts\" | timechart span=10m count as \"ISE Fehlversuche\"",
                "enableSmartSources": true
            }
        },
        "ds_rings": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.network.health_score\" BY building\n| eval key=building, name=\"Haus \".building, value=round(v, 1), unit=\"\", min=0, max=10, warn=7, crit=4, better=\"higher\" | table name value unit min max warn crit better key",
                "enableSmartSources": true
            },
            "name": "Health je Haus"
        },
        "ds_heat": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_sakh_metrics metric_name=\"sakh.network.health_score\" building=\"$building$\" device_family=\"Switches and Hubs\" BY device span=10m\n| timechart span=10m limit=0 avg(value) by device",
                "enableSmartSources": true
            },
            "name": "Health je Switch"
        },
        "ds_issues": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:dnac:issue\" Building=\"$building$\"\n| stats latest(_time) as t latest(Name) as Issue latest(Priority) as Prio latest(Category) as Kategorie latest(Description) as Beschreibung latest(Status) as Status by IssueID DeviceName\n| eval Zeit=strftime(t, \"%d.%m. %H:%M\") | sort Prio - t | table Zeit Prio DeviceName Issue Kategorie Status Beschreibung | rename DeviceName as Geraet | head 30",
                "enableSmartSources": true
            }
        },
        "ds_down": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_health",
                "query": "| where Reachability!=\"Reachable\" OR HealthScore<7\n| table DeviceName DeviceType Role Building Location SoftwareVersion HealthScore Reachability\n| rename DeviceName as Geraet DeviceType as Modell Role as Rolle Building as Haus Location as Standort SoftwareVersion as Software HealthScore as Health Reachability as Erreichbarkeit"
            }
        },
        "ds_ise": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ise:syslog\" | rex \"(?<ise_category>CISE_\\w+)\" | rex \"NetworkDeviceName=(?<nad>[^,]+)\" | rex \"EndPointMatchedProfile=(?<profile>[^,]+)\" | rex \"#SAKH#Haus (?<ise_building>[A-D])\" | rex \"FailureReason=(?<failure_reason>[^,]+)\" | search ise_building=\"$building$\" OR NOT ise_building=*\n| eval Ergebnis=if(ise_category=\"CISE_Failed_Attempts\", \"fehlgeschlagen\", \"erfolgreich\") | timechart span=10m count by Ergebnis",
                "enableSmartSources": true
            },
            "name": "ISE RADIUS"
        },
        "ds_ise_profile": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ise:syslog\" | rex \"(?<ise_category>CISE_\\w+)\" | rex \"NetworkDeviceName=(?<nad>[^,]+)\" | rex \"EndPointMatchedProfile=(?<profile>[^,]+)\" | rex \"#SAKH#Haus (?<ise_building>[A-D])\" | rex \"FailureReason=(?<failure_reason>[^,]+)\" | stats count by profile | sort - count | rename profile as \"ISE Profil\"",
                "enableSmartSources": true
            }
        },
        "ds_ise_fail": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ise:syslog\" \"CISE_Failed_Attempts\" | rex \"(?<ise_category>CISE_\\w+)\" | rex \"NetworkDeviceName=(?<nad>[^,]+)\" | rex \"EndPointMatchedProfile=(?<profile>[^,]+)\" | rex \"#SAKH#Haus (?<ise_building>[A-D])\" | rex \"FailureReason=(?<failure_reason>[^,]+)\"\n| stats count as Fehlversuche latest(failure_reason) as Grund by nad ise_building | sort - Fehlversuche | head 12 | rename nad as Switch ise_building as Haus",
                "enableSmartSources": true
            }
        },
        "ds_te": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.te.latency_ms\", \"sakh.te.loss_pct\") BY metric_name agent span=10m\n| eval series=agent.\" \".if(metric_name=\"sakh.te.loss_pct\", \"Verlust %\", \"Latenz ms\") | timechart span=10m avg(v) by series",
                "enableSmartSources": true
            },
            "name": "ThousandEyes"
        },
        "ds_syslog": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:ios\" | rex \"^<\\d+>\\d+: (?<device>[^:]+): [^%]+%(?<facility>[A-Z0-9_]+)-(?<severity>\\d)-(?<mnemonic>[A-Z0-9_]+): (?<message_text>.*)\" | search device=\"$device$\" | where severity<=4\n| eval Zeit=strftime(_time, \"%d.%m. %H:%M:%S\") | table Zeit device severity facility mnemonic message_text\n| rename device as Geraet severity as Sev facility as Facility mnemonic as Mnemonic message_text as Meldung | head 60",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
